mapper.update:
update qms_sampling_plan
   set plan_nm = #{f.planNm}, method = #{f.method}, fixed_n = #{f.fixedN}, pct = #{f.pct}, std_cd = #{f.stdCd},
       insp_level = #{f.inspLevel}, severity = #{f.severity}, aql = #{f.aql}, ac = #{f.ac}, re = #{f.re},
       sort_no = #{f.sortNo}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where sampling_plan_id = #{id} and row_ver = #{f.rowVer}
